function rebrand(value, internationalWord) {
  if (typeof value === "string") {
    return value
      .replaceAll("SUGARGOO", "USFANS")
      .replaceAll("Sugargoo", "USFans")
      .replaceAll("UK", internationalWord);
  }
  if (Array.isArray(value)) return value.map((item) => rebrand(item, internationalWord));
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, rebrand(item, internationalWord)]));
  }
  return value;
}

