translationsByLanguage.de.articleTitles["beginner-ordering-guide"] = ["USFans für Einsteiger: vom Produktlink zum internationalen Paket", "Ein klarer Ablauf für Auswahl, Zahlung, Lagerprüfung, Rückgabe und Versand."];
translationsByLanguage.es.articleTitles["beginner-ordering-guide"] = ["Cómo comprar con USFans: guía completa para principiantes", "Del enlace y la variante al QC de almacén, la devolución y el paquete internacional."];
translationsByLanguage.fr.articleTitles["beginner-ordering-guide"] = ["Acheter avec USFans : guide complet pour débutants", "Du lien produit et de la variante au contrôle en entrepôt, au retour et au colis international."];
translationsByLanguage.it.articleTitles["beginner-ordering-guide"] = ["Come acquistare con USFans: guida completa per principianti", "Dal link e dalla variante al QC in magazzino, al reso e al pacco internazionale."];

translationsByLanguage.en.articleTitles["warehouse-returns-guide"] = ["USFans Warehouse & Returns: A Practical Timing Guide", "How to review warehouse evidence, use the live five-day notice carefully and keep returns, refunds and storage decisions separate."];
translationsByLanguage.de.articleTitles["warehouse-returns-guide"] = ["USFans Lager und Rückgabe: Fristen richtig nutzen", "Lagerbelege prüfen, die aktuelle Fünf-Tage-Angabe einordnen und Rückgabe, Erstattung und Lagerung trennen."];
translationsByLanguage.es.articleTitles["warehouse-returns-guide"] = ["Almacén y devoluciones de USFans: guía práctica de plazos", "Cómo revisar pruebas, interpretar el aviso de cinco días y separar devolución, reembolso y almacenamiento."];
translationsByLanguage.fr.articleTitles["warehouse-returns-guide"] = ["Entrepôt et retours USFans : guide pratique des délais", "Contrôler les preuves, interpréter la mention de cinq jours et distinguer retour, remboursement et stockage."];
translationsByLanguage.it.articleTitles["warehouse-returns-guide"] = ["Magazzino e resi USFans: guida pratica alle tempistiche", "Controllare le prove, leggere correttamente l’avviso di cinque giorni e separare reso, rimborso e deposito."];

translationsByLanguage.en.common.articleImageCaption = "Live catalogue reference image. Use the warehouse photo set and measurements—not the product thumbnail—for the inspection decision.";
translationsByLanguage.de.common.articleImageCaption = "Referenzbild aus dem Live-Katalog. Für die Prüfung zählen Lagerfotos und Maße, nicht das Produktbild.";
translationsByLanguage.es.common.articleImageCaption = "Imagen de referencia del catálogo. Para decidir, usa las fotos y medidas de almacén, no la miniatura.";
translationsByLanguage.fr.common.articleImageCaption = "Image de référence du catalogue. Pour décider, utilisez les photos et mesures d’entrepôt, pas la vignette.";
translationsByLanguage.it.common.articleImageCaption = "Immagine di riferimento del catalogo. Per decidere usa foto e misure di magazzino, non la miniatura.";

translationsByLanguage.en.guideSteps[3][1] = "After warehouse receipt, USFans says it inspects the item; current product notices advertise 3–7 free HD QC photos. Review them as soon as they appear.";
translationsByLanguage.de.guideSteps[3][1] = "Nach dem Lagereingang prüft USFans den Artikel; aktuelle Produktseiten nennen 3–7 kostenlose HD-QC-Fotos. Prüfe sie sofort nach Erscheinen.";
translationsByLanguage.es.guideSteps[3][1] = "Tras la recepción, USFans inspecciona el artículo; los avisos actuales indican 3–7 fotos QC HD gratuitas. Revísalas en cuanto aparezcan.";
translationsByLanguage.fr.guideSteps[3][1] = "Après réception, USFans contrôle l’article ; les fiches actuelles annoncent 3 à 7 photos QC HD gratuites. Examinez-les dès leur publication.";
translationsByLanguage.it.guideSteps[3][1] = "Dopo la ricezione, USFans controlla l’articolo; gli avvisi attuali indicano 3–7 foto QC HD gratuite. Esaminale appena disponibili.";

translationsByLanguage.en.faq[3][1] = "USFans product notices say paid orders are handled during 09:00–18:00 UTC+8. The seller then dispatches domestically; after warehouse receipt, current notices advertise 3–7 free HD QC photos before parcel submission.";
translationsByLanguage.en.faq[4][1] = "No. The photos document visible condition and the received variant. They cannot prove authenticity, comfort, internal construction, exact composition or long-term durability.";
translationsByLanguage.en.faq[6][1] = "Final freight depends on measured actual weight, packed dimensions, volumetric rules, route and packaging. USFans says final cost often varies about ±5–10% from the estimate.";
translationsByLanguage.en.faq[8][1] = "Current product notices commonly mention applying within 5 days after warehouse arrival, but seller rules and product-specific exclusions still apply. Submit clear evidence promptly.";

translationsByLanguage.de.faq[3][1] = "USFans nennt für bezahlte Bestellungen eine Bearbeitung von 09:00–18:00 UTC+8. Danach versendet der Verkäufer im Inland; nach Lagereingang werden aktuell 3–7 kostenlose HD-QC-Fotos genannt.";
translationsByLanguage.de.faq[4][1] = "Nein. Fotos zeigen sichtbaren Zustand und Variante, aber nicht Echtheit, Komfort, Innenaufbau, genaue Zusammensetzung oder Haltbarkeit.";
translationsByLanguage.de.faq[6][1] = "Endfracht hängt von Istgewicht, Packmaß, Volumenregeln, Route und Verpackung ab. USFans nennt oft etwa ±5–10 % Abweichung von der Schätzung.";
translationsByLanguage.de.faq[8][1] = "Aktuelle Produktseiten nennen häufig einen Antrag innerhalb von 5 Tagen nach Lagereingang; Verkäuferregeln und Ausschlüsse gelten weiterhin. Reiche Belege schnell ein.";

translationsByLanguage.es.faq[3][1] = "USFans indica que los pedidos pagados se tramitan de 09:00 a 18:00 UTC+8. Después el vendedor envía al almacén; los avisos actuales anuncian 3–7 fotos QC HD gratuitas.";
translationsByLanguage.es.faq[4][1] = "No. Las fotos muestran estado visible y variante recibida, pero no autenticidad, comodidad, construcción interna, composición exacta o durabilidad.";
translationsByLanguage.es.faq[6][1] = "El flete final depende del peso real, dimensiones embaladas, reglas volumétricas, ruta y embalaje. USFans señala una variación habitual de aproximadamente ±5–10 %.";
translationsByLanguage.es.faq[8][1] = "Los avisos actuales suelen mencionar una solicitud dentro de 5 días tras la llegada al almacén; siguen aplicando las reglas y exclusiones del vendedor. Presenta pruebas pronto.";

translationsByLanguage.fr.faq[3][1] = "USFans indique que les commandes payées sont traitées de 09:00 à 18:00 UTC+8. Le vendeur expédie ensuite vers l’entrepôt ; les fiches actuelles annoncent 3 à 7 photos QC HD gratuites.";
translationsByLanguage.fr.faq[4][1] = "Non. Les photos montrent l’état visible et la variante reçue, mais pas l’authenticité, le confort, la construction interne, la composition exacte ou la durabilité.";
translationsByLanguage.fr.faq[6][1] = "Le fret final dépend du poids réel, des dimensions emballées, des règles volumétriques, de la route et de l’emballage. USFans indique souvent un écart d’environ ±5–10 %.";
translationsByLanguage.fr.faq[8][1] = "Les fiches actuelles mentionnent souvent une demande sous 5 jours après l’arrivée en entrepôt ; les règles et exclusions du vendeur restent applicables. Envoyez rapidement les preuves.";

translationsByLanguage.it.faq[3][1] = "USFans indica che gli ordini pagati vengono gestiti tra le 09:00 e le 18:00 UTC+8. Il venditore spedisce poi al magazzino; gli avvisi attuali indicano 3–7 foto QC HD gratuite.";
translationsByLanguage.it.faq[4][1] = "No. Le foto mostrano stato visibile e variante ricevuta, ma non autenticità, comfort, costruzione interna, composizione esatta o durata.";
translationsByLanguage.it.faq[6][1] = "Il costo finale dipende da peso reale, dimensioni imballate, regole volumetriche, rotta e imballo. USFans indica spesso uno scostamento di circa ±5–10%.";
translationsByLanguage.it.faq[8][1] = "Gli avvisi attuali citano spesso una richiesta entro 5 giorni dall’arrivo in magazzino; valgono comunque regole ed esclusioni del venditore. Invia subito prove chiare.";

